      "canonicalText": "穆王將徵犬戎，祭公謀父諫曰：「不可。先王耀德不觀兵。夫兵戢而時動，動則威，觀則玩，玩則無震。是故先王之於民也，懋帥其德而廣其振宿，料其動意而政之以禮。發祥明義，以顯道而遏淫慝，是故先王無不聽，無遠不思，無不順，無不從。」",
