      "readingAid": {
        "translation": "周恭王巡遊來到涇水河畔，密國國君密康公隨從護駕，當時有同胞三位絕美女子主動投奔密康公。密康公的母親勸告他說：你必須立刻把這三位女子進獻給天子恭王！獸聚三隻就成為獸羣，人聚三人就成為人羣，女子三人同美就成為燦爛尤物（女三為粲）！周天子狩獵時絕不獵取全部獸羣，諸侯出行時絕不役使全部民眾，天子侍妾亦不會同時迎娶同一家族的三位女子！所謂粲麗尤物，是世間極美之物啊！大家把極美的尤物歸附於你，你有什麼崇高德行能夠承受承擔得起呢？連周天子尚且承受不起過度尤物，何況你這個微不足道的偏狹小邦國君呢（小醜）！微小之邦若獨自霸佔極致尤物，最終必定會招致國破家亡！密康公執迷不悟不肯進獻，一年後周恭王果然發兵滅亡了密國！",
        "analysis": "【題解與密康公母論三女為粲與小醜備物必亡】本段記載密康公之母深明大義、以「女三為粲、小醜備物終必亡」精闢剖析德不配位、獨佔尤物必招奇禍之哲理。\\n【詞義訓詁】「密康公」：西周密國（今甘肅靈臺）國君；「女三為粲」：粲，美物尤物；三位美女同聚；「小醜」：謙詞，微小諸侯國；「小醜備物終必亡」：自身德薄力弱卻獨佔極盛之物，必招滅頂之災。\\n【德位匹配哲學】世間極致之資源與尤物皆伴隨著極大風險。弱小勢力若不知節制收斂、妄圖獨吞大美，終將引火燒身。"
      }
