      "canonicalText": "厲王虐，國人謗王。邵公告曰：「民不堪命矣！」王怒，得衛巫，使監謗者，以告，則殺之。國人莫敢言，道路以目。王喜，告邵公曰：「吾能弭謗矣，乃不敢言。」邵公曰：「是障之也。防民之口，甚於防川。川壅而潰，傷人必多，民亦如之。是故為川者決之使導，為民者宣之使言。」",
