      "readingAid": {
        "translation": "周厲王統治殘暴苛虐，鎬京的國人百姓紛紛公開議論批評周厲王（國人謗王）。召穆公（邵公）向周厲王進言告誡說：百姓已經無法忍受苛政暴政的折磨了！周厲王勃然大怒，找來衛國的巫師，派遣他祕密監視偵察敢於批評朝政的人；只要衛巫密報告發，厲王就立刻將其殘酷處死！鎬京全城百姓再也沒有人敢公開說話，在道路上相遇時只能用眼神互相示意恐懼（道路以目）！周厲王沾沾自喜，得意地對召公說：我終於有能力徹底消除天下人的批評誹謗了（吾能弭謗矣），如今百姓再也不敢胡說八道了！召公沉痛地進諫說：這只是強行堵塞言路罷了（是障之也）！防範壓制百姓的言論批評，比防堵洶湧的江河水患危害還要嚴重得多（防民之口，甚於防川）！江河河道一旦被強行堵塞積聚而決口崩潰，溺死傷害的人必定極其慘重；壓制百姓的言論民意，後果也是完全一樣的！所以善於治理江河水利的人必定疏通決開河道引導水流奔瀉，善於治理天下萬民的人必定廣開言路引導百姓暢所欲言！",
        "analysis": "【題解與防民之口甚於防川召公諫厲王弭謗】本段為中國政治文明史與言論自由哲學最震撼之千古名篇——召穆公以「防民之口甚於防川、川壅而潰傷人必多」痛斥特務統治與鉗口政策！\\n【詞義訓詁】「謗王」：公開議論批評君王施政失誤；「衛巫監謗」：古代特務情報告密體制；「道路以目」：恐怖統治下民眾敢怒不敢言；「防民之口甚於防川」：千古格言；「宣之使言」：宣通導，疏導引導人民自由表達意見。\\n【政治反饋機制之生命線】言路是政權了解社會矛盾的唯一定位儀與減壓閥。以暴力封堵批評只能掩蓋矛盾，最終積蓄的民間憤怒必將如決堤洪水般徹底摧毀統治階級（引發國人暴動、厲王流彘）。"
      }
