      "canonicalText": "厲王說榮夷公，芮良夫曰：「王室其將卑乎！夫榮公好專利而不知大難。夫利，百物之所生也，天地之所載也，而或專之，其害多矣。天地百物皆將取焉，胡可專也？所利大，其謀亦大；所害多，其怨亦多。匹夫專利，猶謂之盜，王而若然，其何以庇天下？」",
