        "analysis": "【題解與芮良夫諫厲王專利匹夫專利猶謂之盜】本段記錄芮良夫痛斥周厲王與榮夷公「國家專利（山林川澤國有壟斷、剝奪民生）」的經典經濟倫理批判！\\n【詞義訓詁】「榮夷公」：周厲王卿士，主持山林川澤專利改革；「專利」：官府獨占壟斷山林川澤產權與收益；「匹夫專利猶謂之盜」：痛斥與民爭利等同強盜行徑；「何以庇天下」：君主喪失庇護人民之合法性。\\n【公共資源與民生底線】山林川澤是底層百姓採樵捕撈、維持基本生存的天然資源。統治者一旦將其全部壟斷專營，直接切斷底層百姓生路，政權必遭民眾烈火般反噬。"
