        "analysis": "【題解與彘之亂邵公以己子代宣王捨生取義】本段記載西周末年「國人暴動（彘之亂）」中，召穆公以親生骨肉替換太子姬靜（宣王）赴難之壯烈史實。\\n【詞義訓詁】「彘之亂」：公元前841年國人暴動，周厲王逃奔彘（今山西霍縣），開啟共和行政；「邵公」：召穆公虎；「以己子代宣王」：捨己之子保全王室唯一血脈，千古忠烈。\\n【政治責任與道德崇高】召穆公忠直敢諫於前、捨己救國於後，展現了周代貴族在體制崩潰絕境中維繫文明薪火的崇高犧牲精神。"
