      "order": 9,
      "canonicalText": "宣王即位，不籍千畝。虢文公諫曰：「不可。夫民之大事在農，上帝之粢盛於是乎出，民之蕃庶於是乎生，事神保民，莫大於農。故古者先王必藉千畝，以身帥之，天子親耕，以昭大物也。」",
