        "translation": "在籍田大禮舉行的前五天，盲人樂官（瞽官）前來稟報溫暖的東風（協風）已經吹拂大地，周天子便立刻進入齋戒宮室淨化身心，文武百官與主管各項事務的官員，亦各自進入專門的齋戒之所虔誠齋戒整整三天！周天子純潔沐浴、品嘗甜醴祭品，到了春耕吉日大典之時，鬱人官員獻上鬱金香草釀造的香酒（鬯酒），宗伯與祝官贊禮協助祭祀，周天子親手握持象徵農耕的木犁耒耜，在王田中親自往返推耕三次！",
