      "readingAid": {
        "translation": "虢文公勸諫說：在那個時候，國家的政事只以農業為首要任務，不會為了謀取官府的利益而妨礙農業生產。春、夏、秋三季都專心務農，只有在冬季才進行軍事訓練。因此，出兵征伐時就會有強大的威勢，防守時就會有充足的財力。如今大王您廢除了藉田之禮，這等於是放棄了國家的根本啊。然而，周宣王最終還是沒有聽從這個勸告。",
        "analysis": "【訓詁與名物】「王事唯農是務」是賓語前置句，意即「王事唯務農」，國家的政事只致力於農業。「幹」通「幹」，幹擾、妨礙。「三時」指春、夏、秋三季。「一時」指冬季，古人常於農閒的冬季舉行田獵以演練武事。「講武」指講習武事、軍事訓練。「棄本」指放棄農業這個立國之本。「藉田」是古代天子親耕以示重農的典禮。\\n【章法與結構】本段是臣子勸諫君王的言辭片段。先回顧先王時期的優良傳統，說明「重農」與「講武」的時間分配（三時務農，一時講武），並推導出其帶來的富國強兵之效（徵則有威，守則有財）；接著筆鋒一轉，批評當今周宣王廢除藉田禮的行為是「棄本」；最後以「宣王不聽」四字作結，帶出濃厚的歷史遺憾與悲劇色彩。\\n【思想與義理】這段記載反映了中國古代根深蒂固的「農本思想」與「寓兵於農」的軍事理念。農業被視為國家生存與軍事實力的絕對基礎。虢文公的勸諫，強調了統治者必須順應農時，不可因官府的私利或頻繁的軍事行動而幹擾百姓生產。宣王的不聽勸阻，在《國語》的史觀中，被視為周朝國力衰退、禮崩樂壞的重要徵兆，具有強烈的政治警示意味。"
      }
