      "id": "guo-yu_ch-1_p-15",
      "chapterId": "guo-yu_ch-1",
      "order": 15,
      "canonicalText": "三十二年春，宣王伐魯，立孝公，諸侯從是而不睦。宣王欲得國子之能導訓諸侯者，樊穆仲曰：「魯侯孝公敬事神明，惠愛百姓，能修舊業，其可使訓導諸侯乎。」王乃使魯侯導諸侯。",
      "sentenceIds": [
        "guo-yu_ch-1_p-15_s-1",
        "guo-yu_ch-1_p-15_s-2",
        "guo-yu_ch-1_p-15_s-3"
      ],
      "sourceRefs": [
        {
          "label": "經文底本",
          "edition": "dianji.fun",
          "url": "https://ctext.org/guo-yu/zh"
        },
        {
          "label": "維基文庫《國語》全文",
          "edition": "維基文庫繁體全文頁（人工開啟核實 2026-08-14）",
          "url": "https://zh.wikisource.org/wiki/%E5%9C%8B%E8%AA%9E"
        }
      ],
      "readingAid": {
        "translation": "周宣王三十二年春天，周宣王派兵討伐魯國，強行擁立魯孝公為君主，各國諸侯從此便與周王室不再和睦。宣王想要尋找一位能夠引導和訓誡各國諸侯的國君，大夫樊穆仲推薦說：魯侯孝公恭敬地侍奉神明，施恩愛護百姓，能夠繼承並修明祖先傳下來的基業，或許可以讓他去訓導各國諸侯吧。於是，周宣王便派魯侯去引導各國諸侯。",
        "analysis": "【訓詁與名物】：「宣王」即周宣王，西周晚期的君主。「伐魯，立孝公」指宣王干涉魯國君位繼承，廢長立幼（強立魯孝公），這是違背周禮的。「國子」指諸侯國的國君。「導訓」指引導、訓導。「樊穆仲」為周朝的大夫。「修舊業」指繼承並發揚祖先（周公、伯禽）的德政與法度。\\n\\n【章法與結構】：本段敘事極簡，先交代背景與起因：宣王伐魯立孝公導致「諸侯不睦」，這是一個重大的政治危機。隨後寫宣王的應對策略：尋找「能導訓諸侯者」。最後通過樊穆仲的舉薦，點出魯孝公具備「敬神」、「愛民」、「修業」三大德行，從而順理成章地被委以重任。因果關係明確，情節緊湊。\\n\\n【思想與義理】：這段記載暴露了西周晚期王權衰落與禮崩樂壞的端倪。周宣王憑藉武力干涉魯國內政，破壞了宗法制度的嫡長子繼承製，導致諸侯離心（不睦），這是他政治上的一大敗筆。然而，隨後他試圖通過推舉有德行的魯孝公來「導訓諸侯」，試圖用魯國的「禮義之邦」形象來彌補王室威信的喪失，挽回諸侯的向心力。這反映了統治者在面臨危機時，仍試圖依賴「德治」與「禮教」來維繫政治秩序的無奈與嘗試。"
      }
