      "canonicalText": "宣王既喪南國之師，乃料民於太原。仲山父諫曰：「民不可料也！夫古者不料民而知其少多，司民協孤，司商協質，司寇協獄，司土協田，各守其職，則戶口之數自明。今料民於太原，是暴其寡也，且擾民生怨，不可為也。」宣王不聽，卒料之。",
