      "order": 17,
      "canonicalText": "幽王二年，西周三川皆震。伯陽父曰：「周將亡矣！夫天地之氣，不失其序；若過其序，民亂之也。陽伏而不能出，陰迫而不能蒸，於是有地震。今三川皆震，是陽失其所而鎮陰也。陽失而在陰，川源必塞；源塞，國必亡。昔伊、洛竭而夏亡，河竭而商亡。今周德如二代之季矣，其川源又塞，塞必竭。夫國必依山川，山崩川竭，亡之徵也。若國亡不過十年，數之紀也。天之所棄，不過其紀。」是歲也，三川竭，岐山崩。十一年，幽王乃滅，周乃東遷。",
