      "canonicalText": "惠王三年，邊伯、石速、蒍國出王而立子頹。王處於鄭三年。王子頹飲三大夫酒，子國為客，樂及遍舞。鄭伯聞之，見虢叔曰：「寡人聞之，哀樂不時，殃咎必至。今王子頹歌舞不倦，樂及遍舞，是忘其憂而玩其殃也。禍必及之，我其納王乎。」虢叔許之。四年春，鄭伯、虢叔奉王以伐京師，殺子頹及五大夫，王乃復位。",
