      "canonicalText": "十五年，有神降於莘，王問於內史過，曰：「是何故？固有之乎？」對曰：「有之。國之將興，其君齊明、衷正、純潔、惠和，其德足以昭其馨香，其惠足以明其施捨。民思其德，遠神降福，故神降之，觀其政德而賜之福。國之將亡，其君貪冒、辟邪、淫慝、荒怠，其德足以致其怨讟，其政足以殘其民物。民怨其上，妖孽降殃，故神亦降之，觀其苛慝而加之禍。故神降，興亡之兆也。」",
