      "order": 22,
      "canonicalText": "襄王使邵公過及內史過賜晉惠公命，呂甥、郤芮相晉侯不敬，晉侯執玉卑，拜不稽首。內史過歸，以告王曰：「晉侯其無後乎！王賜之命而晉侯怠，是怠天命也。呂、郤又相之以不敬，是棄禮也。棄禮無親，怠天無福。晉必有咎。」",
