      "readingAid": {
        "translation": "周襄王派邵公過和內史過前往晉國，賜予晉惠公正式的諸侯冊命。在舉行儀式時，呂甥和郤芮這兩位大臣作為儐相輔佐晉侯，表現得很不恭敬；晉惠公自己拿著玉圭的姿勢很低，行拜禮時頭也沒有觸地。內史過回到周朝後，把這件事報告給襄王說：晉侯恐怕會沒有後嗣吧！天子賜給他冊命，他卻表現得怠慢，這就是對天命的怠慢。呂甥和郤芮輔助他時又不恭敬，這就是拋棄了禮節。拋棄禮節就無法得到國內外的親附，怠慢天命就無法獲得神明的福佑。晉國必定會遭遇災禍。",
        "analysis": "【訓詁與名物】：「襄王」指周襄王。「賜命」指天子正式冊封諸侯。「相」指在典禮上從旁引導、輔助。「執玉卑」指拿著玉器的位置過低，古代禮節中執玉的高低代表了敬意的深淺。「稽首」是古代最隆重的跪拜禮，頭必須觸地。「無後」指沒有後代繼承君位。「怠」指輕慢。「咎」指災禍。\\n\\n【章法與結構】：本段敘事極具戲劇張力。前半部分是客觀的動作描寫，通過「相晉侯不敬」、「執玉卑」、「不稽首」三個具體的細節，生動地刻畫了晉惠公君臣傲慢無禮的姿態。後半部分則是內史過的嚴厲評判，他將這些細微的禮儀失當上升到了「怠天命」與「棄禮」的高度，並以此推導出「無後」和「有咎」的政治預言，邏輯嚴密，見微知著。\\n\\n【思想與義理】：這段記載深刻體現了先秦時代「禮儀即政治」的觀念。在古人看來，禮儀絕非單純的形式，而是內心敬畏與政治秩序的外化。晉惠公君臣在天子使者面前的傲慢，暴露出他們對周天子（天命代表）的蔑視與自身道德修養的缺失。這種「棄禮」與「怠命」的心態，必然會導致他們在內政外交上眾叛親離（無親、無福）。這警示統治者，細節中的驕傲往往是政權敗亡的先兆。"
      }
