      "canonicalText": "「古者，先王既有天下，又崇立上帝、明神而敬事之，於是乎有朝日、夕月以教民事君。諸侯春秋受職，各恭其事，修其禮儀，以相敬肅。今晉侯怠於王命，是蔑天子也。」",
