      "readingAid": {
        "translation": "在古時候，先王既然已經擁有了天下，還要尊崇並確立對上帝和神明的祭祀，恭敬地侍奉他們，因此纔有了春天早晨祭日、秋天傍晚祭月的儀式，以此來教導百姓如何恭敬地侍奉君主。各國諸侯在春秋兩季來到王廷接受職務與政令，各自恭敬地做好自己的本職工作，修明禮儀，以此來相互保持敬畏與肅穆。如今晉侯對天子賜予的冊命如此怠慢，這完全是在蔑視天子啊。",
        "analysis": "【訓詁與名物】：「先王」指古代的聖王。「崇立」指尊崇並確立祭祀。「上帝、明神」指天上的最高神靈及日月星辰等神明。「朝日」指春天早晨祭祀太陽。「夕月」指秋天傍晚祭祀月亮。「受職」指接受天子分配的職務與政令。「敬肅」指恭敬肅穆。「蔑」指輕視、蔑視。\\n\\n【章法與結構】：此段是內史過論述「敬天法祖」之禮的延續。開篇以「古者先王」起筆，追溯了祭祀禮儀（朝日、夕月）的起源與教化目的（教民事君）；然後引申到諸侯的臣道（春秋受職、修其禮儀）；最後話鋒一轉，將古人的恭敬與「今晉侯」的怠慢進行強烈對比，得出了「蔑天子也」的結論。借古非今，氣勢磅礡。\\n\\n【思想與義理】：本段闡述了西周禮樂文化中「神道設教」與「以禮治國」的核心邏輯。先王祭祀日月神明，表面上是敬鬼神，實質上是為了在人間建立一種等級森嚴、充滿敬畏的倫理秩序（教民事君）。諸侯對天子的恭敬，是維持整個天下太平（相敬肅）的基石。晉惠公怠慢王命，破壞的不僅是君臣之禮，更是顛覆了這套維繫天下的根本秩序。這體現了周人對於禮樂制度崩潰的深切憂慮。"
      }
