      "readingAid": {
        "translation": "何況晉侯（惠公）本來並不是合法的繼承人，卻僥倖得到了國君的寶座，他本應該勤勉小心、時常感到恐懼，戰戰兢兢地保住自己的位置，即使這樣都還怕做的不夠。如果他反而放縱自己的慾望而疏遠鄰國，欺凌國內的百姓而輕視天子，那他將憑什麼來守住這個國家呢？百姓背叛他，鄰國仇視他，天子對他發怒，臣下對他怨恨，這樣的統治又怎麼可能長久呢？",
        "analysis": "【訓詁與名物】：「非嗣」指晉惠公並非原定的合法繼承人（嫡長子），他是通過政治鬥爭和賄賂纔回國即位的。「亹亹（wěi）」指勤勉不倦。「怵惕」指恐懼、警惕。「保任」指保住並承擔責任。「廣其心」指放縱自己的私慾，驕傲自大。「陵」指欺凌。「卑其上」指輕視天子。「其何能久」指怎麼能長久。\\n\\n【章法與結構】：這段話直指晉惠公的痛處，邏輯層層遞進。首先點出其「非嗣」的尷尬身份，提出他理應具備的態度（亹亹怵惕）；隨後用「若將……將何以……」的假設反問句式，揭露了他驕橫跋扈的真實面目（遠鄰、陵民、卑上）；最後用極其凝練的四字對句「民叛鄰仇，上怒下怨」概括了他四面楚歌的絕境，得出了必然滅亡的結論。說理透徹，令人膽寒。\\n\\n【思想與義理】：這段分析展現了古代政治家深邃的戰略眼光與政治倫理。一個君主權力的穩固，不能僅靠權謀與僥倖，更需要懷有「戒懼」之心。內史過將治國的要素歸結為四個維度：對上敬畏天子，對下愛護百姓，對外結交鄰國，對內收服人心。晉惠公的傲慢恰恰將這四點破壞殆盡，導致了「上怒、下怨、鄰仇、民叛」的死局。這深刻告誡後人，缺乏合法性與道德約束的統治，越是驕狂，敗亡得越快。"
      }
