        "analysis": "【題解與替贄無鎮誣王無民必速及禍】本段內史過以「替贄無鎮、誣王無民」八字蓋棺定論，宣告晉惠公在外交禮儀上的失德將直接引發政治合法性崩塌。\\n【詞義訓詁】「替贄無鎮」：廢棄信物失去了安定國家的依託；「誣王無民」：欺瞞天子君王必將喪失萬民擁戴；「速及禍」：迅速招致滅頂災難。\\n【政治合法性警示】統治者的言行舉止代表國家形象與信用，一旦背棄承諾與法統，政治信用破產後政權將迅速解體。"
