      "canonicalText": "襄王使太宰文公及內史興賜晉文公命，上卿逆於境，晉侯郊勞，館諸宗廟，饋九牢，設庭燎。及期命於廟，晉侯拜受，稽首升成。內史興歸，告王曰：「晉侯必霸！其敬禮也周，其接賓也恪，上敬天子，下親百官，霸業必成。」",
