      "canonicalText": "襄王十三年，鄭人伐滑。王使遊孫伯請滑，鄭人執之。王怒，將以狄伐鄭。富辰諫曰：「不可。古人有言曰：『兄弟鬩於牆，外禦其務。』鄭，周之伯父也，有小怨而棄之，引戎狄以伐同姓，是自拔其本也。且王怒不可長，狄德不可恃，願王圖之。」王不聽，遂以狄伐鄭。",
