      "sourceRefs": [
        {
          "label": "經文底本",
          "edition": "dianji.fun",
          "url": "https://ctext.org/guo-yu/zh"
        },
        {
          "label": "維基文庫《國語》全文",
          "edition": "維基文庫繁體全文頁（人工開啟核實 2026-08-14）",
          "url": "https://zh.wikisource.org/wiki/%E5%9C%8B%E8%AA%9E"
        }
      ],
      "readingAid": {
        "translation": "晉侯派隨會（即士季、範武子）前往周王室進行外交聘問，周定王用餚烝（即將牲肉切碎折斷後進獻）的宴饗之禮來招待他，由原公擔任輔助行禮的儐相。隨會私下裡對原公說：我聽說周王室的最高祭祀與宴饗禮儀，牲肉都是保持完整的，不應該被切割折斷的，今天這到底是什麼禮節呢？原公把隨會的疑問報告給了周定王。",
        "analysis": "【訓詁與名物】：「隨會」即晉國大夫士季，又稱範武子、範子。「聘」指諸侯派大夫去朝問天子或別國。「定王」指周定王。「享」指設宴款待。「餚烝」古代宴饗禮儀之一，烝指把牲肉放在俎（案板）上，餚烝是指將帶骨的肉折斷、切塊後進獻。「相禮」指在典禮中贊禮、引導。「私於」指私下對某人說。「毀折」指將牲肉切割、折斷。\\n\\n【章法與結構】：這是一個典型的「因事生問」的敘事結構。文章首先交代了事件的背景（隨會聘周，定王享之餚烝），然後通過隨會的「私問」（吾聞王室之禮無毀折，今此何禮也），拋出了一個關於禮制規範的疑問。最後以原公「告王」作為過渡，自然地引出了下文周定王對禮制的分級解釋。行文簡潔，懸念頓生。\\n\\n【思想與義理】：隨會的疑問並非無的放矢，而是反映了春秋時期各國大夫對周朝傳統禮樂制度的關注與敏感。在古人眼中，宴會上的牲肉是完整（全烝）還是切碎（餚烝），不僅僅是飲食習慣的不同，更是身份等級與外交規格的嚴格體現。隨會質疑「無毀折」，是以天子祭祀與最高規格朝會的標準來衡量這次宴饗，他誤以為周王室失禮或是輕視晉國。這揭示了禮儀在當時政治交往中作為「無聲語言」的極端重要性。"
      }
