      "chapterId": "guo-yu_ch-2",
      "order": 12,
      "canonicalText": "「夫王公諸侯之有飫也，將以講事成章，建大德、昭大物也，故立成禮烝而已。飫以顯物，宴以合好，各有其道，不可亂也。」",
