      "canonicalText": "定王使單襄公聘於宋。遂假道於陳，以聘於楚。火朝覿矣，道茀不可行，候不在疆，司空不視途，澤不陂，川不梁，野有庾積，而民有飢色。單子見之，深知陳之必亡。",
