      "canonicalText": "「《周制》有之曰：『列樹以表道，立鄙食以守路，國有郊牧，疆有寓望，藪有圃草，囿有林池，所以備水旱也。』今陳國廢其政，道路不通，水旱無備，何以能久？」",
