      "readingAid": {
        "translation": "《周制》上有這樣的規定：在道路兩旁種植樹木來作為標誌，在邊境設立提供飲食的客舍來接待路過的人，國都外圍要有放牧的郊野，邊境上要有供賓客住宿與遠望的館舍，沼澤地裡要有茂盛的水草，園囿中要有樹林和池塘，這些都是用來防備水災和旱災的物資儲備。如今陳國廢棄了這些政令與設施，道路阻塞不通，對水旱災荒也毫無防備，這個國家怎麼能長久存在呢？",
        "analysis": "【訓詁與名物】：「《周制》」指周朝的典章制度。「表道」指作為道路的標誌。「鄙食」指設在邊邑的客舍，提供飲食。「郊牧」指國都外圍供放牧的地方。「寓望」指供賓客住宿並便於登高遠望的館舍，寓指寄宿。「藪（sǒu）」指積水的沼澤地。「圃草」指茂盛的草本植物。「囿」指古代帝王或貴族蓄養禽獸的園林。「林池」指樹林和池塘。\\n\\n【章法與結構】：這是單襄公論證陳國「必亡」的第二層：廢棄政令和基礎設施。他同樣採取了先引經據典、後對比現實的說理結構。他一口氣列舉了《周制》中關於交通、外交接待以及自然資源保護的六項具體規定（列樹、鄙食、郊牧、寓望、藪圃、囿林），展現了一幅理想的國家治理圖景。然後將其與陳國的現狀（廢其政、道路不通、水旱無備）進行強烈對比，以一個反問句「何以能久」有力地結束論證。\\n\\n【思想與義理】：這段論述揭示了古代國家治理的微觀層面。周朝的制度不僅僅是抽象的禮樂，更包含了極為具體的公共設施建設與生態資源管理。種樹標道、建館待客是為了國家交通與外交的順暢；而保護郊牧、藪圃、林池，則是為了涵養自然資源，以備不時之需（備水旱）。陳國對這些基礎建設的全面廢棄，反映了其政府行政機能的徹底癱瘓。一個無法提供基本公共服務、無法應對自然災害的國家，自然無法長久立足。"
      }
