      "readingAid": {
        "translation": "周朝的《秩官》制度上有這樣的規定：當地位對等的諸侯國賓客到來時，守關的長官要向上報告，主管外交的官員要拿著符節去迎接，候人要在前面做嚮導，卿大夫要到國都郊外去慰勞，守門的官員要清掃城門，宗祝等祭祀官員要在太廟裡準備迎接的禮儀。如今陳國完全沒有接待賓客的禮節，這就等於是拋棄了與其他國家的外交關係。拋棄了外交關係就會陷入孤立無援的境地，這就是自取滅亡的道路啊。",
        "analysis": "【訓詁與名物】：「《秩官》」指周朝記載官吏職責與秩序的典籍。「敵國」指地位相等、匹敵的諸侯國。「關尹」把守關隘的官員。「行（háng）理」主管外交與接待賓客的官員。「節」即符節，外交憑證。「逆」指迎接。「候人」在邊境迎送賓客的官員。「除門」指打掃城門，以示尊重。「宗祝」主管宗廟祭祀與祈禱的官員。「棄交」指放棄外交往來。\\n\\n【章法與結構】：這是單襄公論證陳國「必亡」的第三層：廢棄外交禮儀。結構與前兩段如出一轍。他詳細羅列了周制中接待「敵國賓至」的七道嚴格程序（關尹告、行理逆、候人導、卿郊勞、門尹除、宗祝薦），體現了周朝外交禮儀的嚴謹與隆重。隨後一針見血地指出陳國「無賓禮」的現狀，並通過邏輯推理得出「無賓禮→棄交→無援→亡之道」的必然鏈條，結論無可辯駁。\\n\\n【思想與義理】：這段話強調了「外交禮儀」在春秋列國生存博弈中的極端重要性。在那個兼併戰爭頻發的時代，諸侯國之間的「交」不僅僅是迎來送往的面子工程，更是維繫國家安全、結成政治同盟的實質手段。陳國連最基本的賓客之禮都荒廢了（如單襄公假道而無候人），這不僅是傲慢，更是政治上的極度短視。主動切斷與外界的友好聯繫，在弱肉強食的國際環境中，無異於自絕後路。單襄公的這番分析，展現了高超的外交與戰略眼光。"
      }
