      "readingAid": {
        "translation": "先王的教令中曾這樣說過：天道的規律是獎賞善良而懲罰邪惡淫亂，所以凡是我們建立的諸侯國，都不要去遵從那些不合乎常規法度的行為，不要去親近過度逸樂與荒淫的事情，各自堅守你們國家的典章制度，以此來承受上天賜予的福祐。如今陳侯卻與夏氏的女眷發生淫亂的關係，完全拋棄了國家的法典，這簡直就是在加速災禍的降臨啊。",
        "analysis": "【訓詁與名物】：「淫」指過度、邪惡、淫亂。「造國」指建立諸侯國。「無」同毋，不要。「非彝」指不符合常規法度的行為，彝指常道、法度。「即」指親近、靠近。「慆（tāo）淫」指過度沉溺於逸樂與荒淫。「典」指典章制度。「休」指福氣、福祐。「夏氏」指陳國大夫夏徵舒的母親夏姬，陳靈公與其私通。「速」指加速、招致。\\n\\n【章法與結構】：這是單襄公論證陳國「必亡」的第四層，也是最核心的道德與政治指控。他依然採用「先王之令」與「陳侯現狀」對比的模式。先引出先王的「天道賞罰」觀與「守典承休」的政治規矩；然後直指陳靈公的致命敗筆——「淫亂夏氏」，這是一種極其嚴重的道德敗壞與政治失範（棄國典）。最後以「速其禍」作結，推斷出陳國即將迎來毀滅。\\n\\n【思想與義理】：此段論述將國家的興衰直接與君主的道德作風掛鉤。在中國傳統的「天命觀」中，天意並非盲目，而是「賞善罰淫」的道德裁判者。陳靈公作為一國之君，本應是道德的表率與法律的維護者，卻帶頭與臣子的母親（夏姬）私通，這不僅是個人私德的淪喪，更是對整個國家倫理秩序與法典（國典）的公然踐踏。這種統治階級頂層的腐朽與淫亂，必然會招致上天的懲罰（即隨後夏徵舒的弒君叛亂）。"
      }
