      "id": "guo-yu_ch-2_p-22",
      "chapterId": "guo-yu_ch-2",
      "order": 22,
      "canonicalText": "歸，王問魯大夫孰賢？對曰：「季、孟其長處魯乎！叔孫、東門其亡乎！若家不亡，身必不免。」王曰：「何故？」對曰：「夫儉，德之共也；侈，惡之大也。季、孟恭儉以安其位，叔孫、東門驕侈以肆其志。驕侈必亡，自然之數也。」",
